"""PAD and acute limb ischemia: original concise questions for Chapter 13."""
from qbank_json_chapters import question
REFERENCES={
 'pad':('ACC/AHA Lower Extremity PAD Guideline, 2024','https://doi.org/10.1161/CIR.0000000000001251'),
 'cil':('Cilostazol prescribing information, DailyMed','https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7c841eed-a98f-43c3-baaf-bf5502207a69'),
 'best':('BEST-CLI randomized trial, 2022','https://doi.org/10.1056/NEJMoa2207899'),
 'basil':('BASIL-2 randomized trial, 2023','https://doi.org/10.1016/S0140-6736(23)00462-2'),
 'ali':('ESVS Acute Limb Ischaemia Guideline, 2020','https://doi.org/10.1016/j.ejvs.2019.09.006')}
rows=[]
def B(t,*c):return(t,list(c))
def Q(title,stem,answer,others,sections,table=None,ordered=(),flow=None,refs=('pad',),calculation=False):
 r=question('Peripheral arterial disease' if len(rows)<16 else 'Acute limb ischemia',title,stem,answer,others,sections,list(refs),table=table,calculation=calculation)
 r.update(explanationStyle='concise_structured',orderedSections=list(ordered))
 if flow:r['flow']=flow
 rows.append(r)

Q('Calculating the Ankle–Brachial Index','Right and left brachial systolic pressures are 150 and 140 mmHg. Right dorsalis pedis and posterior tibial pressures are 90 and 105 mmHg. What is the right ABI?',
 '0.70',[('0.60','Uses the lower rather than the higher right ankle artery pressure.'),('0.75','Uses the lower rather than the higher brachial pressure as denominator.'),('0.65','Averages ankle pressures instead of using the higher ankle artery pressure.')],
 [('Calculation',[B('**ABI = higher ankle artery pressure / higher brachial pressure.**','Right ABI = max(90,105)/max(150,140) = 105/150 = **0.70**.')]),
 ('Interpretation',[B('**ABI ≤0.90 is abnormal** and supports PAD in the appropriate clinical setting.'),B('**Calculate each leg separately**, using the same higher-arm denominator.','Use standardized supine Doppler measurements; subclavian disease or noncompressible ankle arteries can complicate interpretation.'),B('**ABI alone does not establish CLTI.**','Rest pain, nonhealing tissue loss and objective perfusion assessment determine limb threat.')])],table=(['ABI','Category'],[['≤0.90','Abnormal'],['0.91–0.99','Borderline'],['1.00–1.40','Normal'],['>1.40','Noncompressible']]),calculation=True)

Q('Exercise ABI for Exertional Symptoms','A patient has reproducible calf discomfort while walking, relieved within minutes of stopping. Resting ABI is 1.06. What is the next physiological test?',
 'Treadmill exercise ABI',[('Toe–brachial index as the primary next test','TBI is particularly useful for noncompressible ankle arteries or suspected CLTI; a normal compressible resting ABI with exertional symptoms favors exercise testing.'),('CT angiography before physiological confirmation','CTA defines anatomy when intervention is contemplated or testing is inconclusive; exercise ABI is the appropriate next physiological study here.'),('Repeat resting ABI in one year','Surveillance suits established stable disease; it does not resolve current symptoms that may reveal obstruction only during exercise.')],
 [('Reveal Reduced Flow Reserve',[B('**Exercise increases demand**, exposing a pressure drop across flow-limiting stenoses that may be unapparent at rest.'),B('**Use exercise ABI when symptoms suggest PAD and resting ABI is >0.90 to ≤1.40.**')]),
 ('Interpret with the Protocol',[B('**Assess postexercise ankle pressure, ABI and recovery**, together with reproduction of symptoms.','A >20% ABI fall or >30 mmHg ankle-pressure fall is used in some protocols; criteria vary and are not interchangeable universal rules.'),B('**A normal test prompts alternative diagnoses**, including spinal stenosis and musculoskeletal disease; persistent uncertainty may warrant further vascular assessment.')])])

Q('Noncompressible Ankle Arteries','A patient with diabetes and CKD has a nonhealing toe ulcer, weak pedal pulses and ABI 1.62. Which physiological test is most useful next?',
 'Toe pressure and toe–brachial index with waveforms',[('Repeat ABI using a higher cuff inflation pressure alone','Calcified arteries resist compression; greater cuff pressure does not reliably restore diagnostic accuracy or assess digital perfusion.'),('Exercise ABI as the sole next study','Exercise ABI addresses exertional symptoms with compressible arteries; tissue loss and noncompressibility require toe/local perfusion assessment.'),('Venous reflux ultrasonography','Venous testing suits edema and typical venous ulceration; it does not resolve suspected arterial ischemia with a falsely high ABI.')],
 [('Why ABI Misleads',[B('**Medial calcification in diabetes/CKD** can make ankle arteries poorly compressible and elevate ABI.','A high ABI is not proof of excellent perfusion.')]),
 ('Digital Perfusion',[B('**TBI ≤0.70 is abnormal.**','Digital arteries are generally less affected by noncompressibility; obtain toe waveforms as well as pressure.'),B('**Toe pressure <30 mmHg suggests severe ischemia** and poor healing potential.'),B('**Use TcPO₂ or skin perfusion pressure when toe testing is unavailable or unreliable.**','Combine perfusion, wound and infection assessment; urgently evaluate possible CLTI rather than dismissing the ulcer because ABI is high.')])])

Q('Chronic Limb-Threatening Ischemia','A patient has a painful forefoot ulcer for six weeks, worse pain with elevation, ABI 0.83 and toe pressure 24 mmHg. Which interpretation is best?',
 'CLTI is supported despite an ABI that is not profoundly reduced',[('Claudication alone because ABI is above 0.50','Claudication is exertional discomfort without ischemic rest pain or tissue loss; the persistent ulcer and severely reduced toe pressure indicate greater limb threat.'),('Neuropathic ulceration alone because the ABI is only mildly abnormal','Neuropathy may coexist, but low digital pressure and elevation-related pain establish an important ischemic component requiring vascular evaluation.'),('Acute limb ischemia because toe pressure is below 30 mmHg','ALI is defined by abrupt deterioration, generally under two weeks; a six-week wound with chronic symptoms fits a chronic limb-threat pathway.')],
 [('Clinical and Perfusion Criteria',[B('**Objectively documented PAD plus rest pain, gangrene or ulceration >2 weeks** supports CLTI.','ABI can underestimate severity, particularly with calcification or distal disease.'),B('**Toe pressure 24 mmHg is severely reduced.**','TcPO₂ and skin perfusion pressure can supplement assessment; thresholds predict probability, not certainty, of healing.')]),
 ('Limb-Salvage Care',[B('**Prompt vascular/multidisciplinary evaluation** for revascularization, infection treatment and wound care.'),B('**Offload wounds and manage systemic risk**, including smoking, lipids and diabetes.','Perfusion restoration alone does not replace debridement, infection control or preventive foot care.')])])

Q('Localizing Chronic Arterial Occlusion','A smoker has exertional buttock and thigh pain, reduced femoral pulses and erectile dysfunction. Which arterial distribution best explains the findings?',
 'Aortoiliac occlusive disease',[('Isolated superficial femoral artery disease','Femoropopliteal obstruction commonly causes calf claudication with preserved femoral inflow; it does not explain the full proximal-pulse and pelvic symptom pattern.'),('Isolated tibial arterial disease','Tibial disease chiefly affects distal foot perfusion, often in diabetes; it would not account for reduced femoral pulses.'),('Isolated popliteal artery entrapment','Entrapment can cause exertional calf ischemia, especially in younger active patients; it does not typically produce bilateral pelvic-inflow symptoms.')],
 [('Anatomical Pattern',[B('**Leriche pattern:** aortoiliac obstruction with proximal claudication, reduced femoral pulses and erectile dysfunction.','Symptoms depend on collateral flow and activity; not every patient has the complete triad.')]),
 ('Assessment and Treatment',[B('**Confirm PAD physiologically**, then map anatomy with duplex/CTA/MRA when revascularization is being considered.'),B('**Risk-factor treatment and structured exercise** remain fundamental.'),B('**Revascularization depends on symptoms, anatomy and operative risk.**','Endovascular repair or aortobifemoral bypass may be appropriate; the classic syndrome name alone does not dictate one procedure.')])])

Q('Vascular Versus Neurogenic Claudication','An older adult develops bilateral buttock and leg discomfort while standing or walking. Sitting or bending forward relieves symptoms; simply standing still does not. Pedal pulses and resting/exercise ABI are normal. Which diagnosis is most likely?',
 'Lumbar spinal stenosis',[('Aortoiliac occlusive disease','Aortoiliac disease can cause proximal exertional pain, but vascular pain generally improves with rest without requiring flexion and often has abnormal pulse/physiological findings.'),('Chronic venous outflow obstruction','Venous claudication causes bursting discomfort and swelling, often relieved by elevation; the posture-dependent flexion pattern is more characteristic of spinal stenosis.'),('Hip osteoarthritis','Hip disease causes joint-related pain and restricted movement; the supplied bilateral posture-dependent leg syndrome with walking favors neurogenic claudication.')],
 [('Discriminating Features',[B('**Neurogenic symptoms depend on lumbar posture.**','Flexion can enlarge the spinal canal; walking distance may vary and cycling may be better tolerated.'),B('**Vascular claudication tracks muscle demand.**','It is often reproducible and resolves after stopping without a specific spinal position.')]),
 ('Avoid False Dichotomies',[B('**Spinal and vascular disease can coexist.**','A normal resting ABI alone would not exclude PAD; here normal exercise physiology also supports the alternative.'),B('**Neurological examination and appropriate spinal imaging** follow the clinical assessment; assess red flags urgently when present.')])])

Q('Lipid Lowering in Symptomatic PAD','A patient with symptomatic PAD takes atorvastatin 80 mg daily with good adherence. LDL cholesterol remains 88 mg/dL. Under the 2024 ACC/AHA PAD guideline, which strategy is appropriate?',
 'Add ezetimibe or a PCSK9 inhibitor to maximally tolerated statin therapy',[('Reduce atorvastatin because LDL is below 100 mg/dL','PAD is clinical ASCVD; an LDL below 100 does not establish optimal risk reduction or justify reducing a tolerated high-intensity statin.'),('Replace atorvastatin with fibrate monotherapy','Fibrates have selected triglyceride-related uses; they do not substitute for proven LDL-lowering therapy in this PAD scenario.'),('Continue statin alone until LDL exceeds 130 mg/dL','The cited framework supports additional therapy at LDL ≥70 mg/dL on maximal statin, not a 130 mg/dL trigger.')],
 [('Treatment Target',[B('**High-intensity statin aims for ≥50% LDL reduction.**','Atorvastatin 40–80 mg or rosuvastatin 20–40 mg daily are standard options.'),B('**2024 ACC/AHA PAD:** adding ezetimibe or a PCSK9 inhibitor is reasonable when LDL remains ≥70 mg/dL on maximal tolerated statin.')]),
 ('Monitor and Individualize',[B('**Confirm adherence, tolerance and secondary causes** before escalating.','Ezetimibe is commonly 10 mg daily; PCSK9 dosing depends on the agent.'),B('**Treat the whole risk profile:** smoking cessation, BP usually <130/80 if tolerated, diabetes therapies with cardiovascular benefit and preventive foot care.')])])

Q('Single Antiplatelet Therapy for PAD','A patient with symptomatic PAD has aspirin-induced urticaria, no recent revascularization and no separate anticoagulation indication. Which long-term antithrombotic regimen is most appropriate?',
 'Clopidogrel 75 mg daily',[('Ticagrelor 90 mg twice daily','Ticagrelor is used in coronary settings, but EUCLID found no superiority over clopidogrel and more treatment discontinuation; clopidogrel has the direct guideline recommendation for symptomatic PAD.'),('Warfarin titrated to INR 2–3','Warfarin treats separate indications such as selected embolic disorders; full anticoagulation solely for PAD adds bleeding without the intended benefit.'),('Rivaroxaban 2.5 mg twice daily alone','The vascular-dose rivaroxaban evidence is in combination with aspirin; this dose alone is not the established substitute for single antiplatelet therapy.')],
 [('Why Clopidogrel',[B('**Single antiplatelet therapy reduces cardiovascular risk in symptomatic PAD.**','Clopidogrel 75 mg daily is an appropriate aspirin alternative; aspirin is another standard agent when tolerated.')]),
 ('Choose Intensity Deliberately',[B('**Dual-pathway inhibition requires both vascular-dose rivaroxaban and low-dose aspirin**, with acceptable bleeding risk.'),B('**Recent procedures or another anticoagulation indication change the regimen.**','Avoid simply stacking agents; assess bleeding, interactions and duration.'),B('**Antiplatelet therapy does not directly restore walking flow reserve**; combine prevention with exercise and symptom-directed treatment.')])])

Q('Dual-Pathway Inhibition After Limb Revascularization','Following lower-extremity revascularization, a patient has low bleeding risk, preserved renal function and no AF or VTE. Which long-term regimen has evidence for reducing cardiovascular and major limb events?',
 'Rivaroxaban 2.5 mg twice daily plus low-dose aspirin',[('Rivaroxaban 20 mg daily plus aspirin','Twenty milligrams is a full-dose anticoagulation regimen for other indications; it is not the vascular-dose strategy studied for this PAD indication.'),('Clopidogrel plus aspirin indefinitely for every such patient','A limited DAPT course can be appropriate after intervention, but indefinite DAPT for everyone is not equivalent to the demonstrated dual-pathway strategy.'),('Dabigatran 150 mg twice daily plus aspirin','This is an anticoagulant dose used in separate indications; it lacks the specified PAD revascularization evidence and adds bleeding exposure.')],
 [('Regimen and Evidence',[B('**Rivaroxaban 2.5 mg twice daily + aspirin 75–100 mg daily** is the dual-pathway regimen.','COMPASS supports selected stable vascular disease; VOYAGER PAD studied patients after lower-extremity revascularization.')]),
 ('Safety Selection',[B('**Check bleeding risk, renal/hepatic function and interacting drugs.**','Avoid active bleeding; previous intracranial bleeding and other exclusions require careful assessment.'),B('**This dose does not replace AF/VTE anticoagulation.**','If a separate full-dose indication exists, redesign the antithrombotic plan rather than adding vascular-dose rivaroxaban.'),B('**Benefit must be weighed against increased bleeding.**')])])

Q('DAPT After Endovascular PAD Treatment','A patient undergoes femoropopliteal endovascular revascularization. The team chooses aspirin plus clopidogrel, with no other indication for prolonged DAPT. What duration range is considered reasonable in the 2024 ACC/AHA PAD guideline?',
 '1–6 months',[('Only the first 24 hours','Periprocedural therapy alone is shorter than the guideline-supported range when DAPT is chosen after endovascular revascularization.'),('At least 18–24 months in every patient','Prolonged DAPT may be required for a separate indication, but that duration is not routinely mandated by peripheral intervention.'),('Lifelong regardless of bleeding risk','Long-term antiplatelet prevention is important; it does not imply indefinite dual therapy without reassessing bleeding and competing indications.')],
 [('Time-Limited Dual Therapy',[B('**DAPT with a P2Y12 inhibitor and low-dose aspirin for 1–6 months is reasonable** after endovascular revascularization.','Choose duration by procedure, ischemic risk, bleeding and other antithrombotic indications.')]),
 ('Avoid Regimen Confusion',[B('**DAPT and dual-pathway inhibition are different strategies.**','The latter uses low-dose rivaroxaban plus aspirin; routine prolonged triple therapy is not the default.'),B('**After the planned course, reassess ongoing prevention.**','Document a stop/review date rather than allowing procedural medication to continue indefinitely.'),B('**A separate coronary stent or AF indication** requires coordinated planning across vascular and cardiac care.')])])

Q('Cilostazol Dose and Interactions','A patient with limiting claudication despite structured exercise has no heart failure but takes diltiazem. If cilostazol is prescribed, which regimen best follows its labeling?',
 '50 mg twice daily, separated from meals',[('100 mg twice daily without dose adjustment','One hundred milligrams twice daily is the usual dose without relevant inhibitors; diltiazem inhibits CYP3A4 and increases exposure.'),('100 mg once daily with the largest meal','Once-daily dosing is not the standard interaction-adjusted regimen; food can increase exposure, so the label advises separation from meals.'),('200 mg twice daily to overcome the interaction','Enzyme inhibition increases rather than decreases cilostazol exposure; escalation would raise adverse-effect risk instead of compensating for reduced efficacy.')],
 [('Mechanism and Dosing',[B('**PDE3 inhibition improves walking symptoms** through antiplatelet and vasodilator effects.','Usual dose: 100 mg twice daily, ≥30 minutes before or ≥2 hours after meals.'),B('**Reduce to 50 mg twice daily** with strong/moderate CYP3A4 inhibitors or CYP2C19 inhibitors.','Examples include diltiazem and omeprazole.')]),
 ('Safety and Follow-up',[B('**Contraindicated in heart failure of any severity.**','Headache, diarrhea and palpitations are common; assess benefit over several weeks and discontinue if ineffective after an adequate trial.'),B('**Cilostazol is symptom therapy**, not a replacement for cardiovascular prevention; pentoxifylline is not recommended for claudication.')])],refs=('pad','cil'))

Q('Structured Exercise for Claudication','A patient with stable claudication asks for an evidence-based walking program. Which prescription best matches standard supervised exercise therapy?',
 'Intermittent walking for 30–45 active minutes, at least 3 times weekly for at least 12 weeks',[('Continuous pain-free walking for 10 minutes twice weekly for 4 weeks','Lower-intensity activity can help conditioning, but this prescription is shorter and less frequent than the standard supervised claudication program.'),('Lower-limb resistance training alone as the initial rehabilitation program','Resistance exercise may complement rehabilitation or suit selected limitations; interval walking is the standard supervised program for ambulatory claudication.'),('Self-directed walking advice with reassessment after six months','General advice is helpful but differs from supervised or structured home-based programs that include behavioral support, progression and follow-up.')],
 [('Program Design',[B('**Walk to moderate or moderately severe claudication, then rest and repeat.**','Active exercise time builds toward 30–45 minutes; sessions also include warm-up and cool-down.'),B('**Minimum typical course:** ≥3 sessions/week for ≥12 weeks.')]),
 ('Implementation',[B('**Structured community/home programs are alternatives** when supervised access is limited.','Use coaching, monitoring and progression; a casual instruction to walk is not equivalent.'),B('**Screen for exercise-limiting cardiac or musculoskeletal disease.**','Rest pain, tissue loss or acute ischemia requires a different assessment; do not apply a claudication exercise prescription to an unstable threatened limb.')])])

Q('When to Revascularize Claudication','A patient remains unable to perform essential daily activities after guideline-directed medical therapy and a completed structured exercise program. Hemodynamically significant femoropopliteal disease is confirmed. What is the appropriate next step?',
 'Discuss revascularization to improve function and quality of life',[('Continue medical treatment until gangrene develops','Tissue loss is not required for symptom-directed revascularization; persistent functionally limiting claudication after appropriate therapy is a valid indication.'),('Perform bypass solely to prevent future progression in every claudicant','Routine prophylactic revascularization is not the indication; here the rationale is current disability despite conservative treatment.'),('Use angiography to choose a procedure without discussing durability or reintervention','Anatomy matters, but shared decisions must include expected functional benefit, procedural risk, durability and potential repeat interventions.')],
 [('Selection',[B('**Confirm symptoms are vascular and important to the patient.**','Revascularization is reasonable after inadequate response to medical treatment including structured exercise.')]),
 ('Procedure and Follow-up',[B('**Endovascular versus surgery depends on anatomy, conduit and risk.**','Autogenous vein is generally preferred for suitable femoropopliteal bypass.'),B('**Discuss durability and reintervention**, especially in long or heavily calcified lesions.'),B('**Continue prevention and exercise after the procedure.**','Revascularization improves local flow but does not cure systemic atherosclerosis or remove the need for antithrombotic and lipid therapy.')])])

Q('WIfI Staging of a Threatened Limb','A diabetic patient has a foot ulcer, toe pressure 25 mmHg and spreading local infection. Which framework most directly combines the three domains needed to estimate threatened-limb severity?',
 'WIfI classification',[('Fontaine classification','Fontaine broadly groups asymptomatic disease, claudication, rest pain and tissue loss; it does not separately grade wound, ischemia and infection.'),('Rutherford chronic PAD category','Chronic Rutherford categories describe symptom/tissue-loss severity but do not provide the same separate infection and physiological grading.'),('Rutherford acute ischemia category','The acute scheme classifies viability using sensory/motor deficits and Doppler signals; it is not the chronic wound–infection framework.')],
 [('Three Domains',[B('**Wound, Ischemia, foot Infection** are each graded 0–3.','The combined pattern informs amputation risk and likely benefit from revascularization, alongside anatomy and patient risk.')]),
 ('Clinical Use',[B('**Toe pressure <30 mmHg corresponds to severe ischemia** in the usual WIfI grading.'),B('**Do not infer a complete WIfI stage from one number.**','Wound depth/extent and infection severity must also be recorded.'),B('**Treat infection and ischemia together.**','Urgent drainage/debridement may be necessary; staged reconstruction and revascularization depend on systemic stability and foot viability.')])],table=(['WIfI ischemia grade','Toe pressure/TcPO₂, mmHg'],[['0','≥60'],['1','40–59'],['2','30–39'],['3','<30']]))

Q('BEST-CLI and Suitable Vein Conduit','In BEST-CLI cohort 1, patients with CLTI were suitable for both approaches and had an adequate single-segment great saphenous vein. Which result was demonstrated?',
 'Bypass reduced major adverse limb events or death compared with endovascular treatment',[('Endovascular treatment reduced the primary composite in this vein-eligible cohort','That reverses the cohort-1 result; bypass had fewer primary events in patients with an adequate single-segment vein.'),('Bypass reduced all-cause mortality as the sole primary endpoint','The primary endpoint combined major adverse limb events and death; the result should not be restated as isolated mortality benefit.'),('The study established identical superiority for bypass when suitable vein was unavailable','Cohort 2 did not demonstrate the same statistically significant benefit; conduit availability limits generalization.')],
 [('Trial Result',[B('**BEST-CLI cohort 1:** primary events 42.6% with surgery versus 57.4% with endovascular therapy; HR 0.68.','The endpoint was major adverse limb event or death, not patency alone; limb events contributed importantly.')]),
 ('Application',[B('**Adequate vein and suitability for both strategies are essential context.**','Results do not mandate bypass for every frail patient or every arterial pattern.'),B('**Assess anatomy, operative risk and goals.**','Autologous conduit availability and wound requirements help select treatment; compare BASIL-2 in its narrower infrapopliteal population rather than treating the trials as interchangeable.')])],refs=('best','pad'))

Q('BASIL-2 and Infrapopliteal Revascularization','Which statement accurately describes BASIL-2 in CLTI requiring infrapopliteal, with or without additional proximal, revascularization?',
 'An endovascular-first strategy improved amputation-free survival, mainly through fewer deaths',[('Vein bypass first improved amputation-free survival in this population','This reverses BASIL-2: major amputation or death was more frequent in the bypass-first group.'),('Endovascular treatment reduced angiographic restenosis as the sole primary endpoint','The primary outcome was major amputation or death, not an isolated angiographic measure of restenosis.'),('The trial compared revascularization against medical therapy without intervention','Both groups received a revascularization-first strategy; it did not test abandoning revascularization for CLTI.')],
 [('Trial Population and Outcome',[B('**BASIL-2:** 345 patients needing infrapopliteal revascularization.','Major amputation/death: 63% bypass-first versus 53% endovascular-first; adjusted HR 1.35 for bypass versus endovascular.'),B('**The difference was largely driven by mortality**, not a universal claim of better limb patency.')]),
 ('Reconciling Trials',[B('**BEST-CLI and BASIL-2 differ in population, anatomy and endpoints.**','An adequate vein may favor bypass in selected BEST-CLI-like patients, but does not erase BASIL-2 evidence in below-knee disease.'),B('**Use multidisciplinary individualized selection**, incorporating frailty, anatomy, conduit, wound and life expectancy.')])],refs=('basil','best'))

Q('Rutherford Acute Limb Ischemia Classification','A patient with six hours of limb ischemia has sensory loss limited to the toes, no motor deficit, absent arterial Doppler signal and preserved venous signal. Which Rutherford category applies?',
 'IIa: marginally threatened',[('I: viable','Category I has no sensory or motor loss and audible arterial/venous signals; toe sensory loss with absent arterial flow exceeds that category.'),('IIb: immediately threatened','IIb generally includes sensory loss beyond the toes and mild/moderate weakness; neither is supplied in this case.'),('III: irreversible','Irreversible ischemia has profound anesthesia and paralysis/rigor, generally with absent arterial and venous signals; those findings are absent here.')],
 [('Bedside Viability',[B('**IIa is salvageable with prompt treatment.**','Motor function is preserved; sensory change is limited, and venous flow remains detectable.')]),
 ('Act on the Category',[B('**Give heparin unless contraindicated and obtain urgent vascular assessment.**','Expedited imaging can guide treatment if it does not delay salvage.'),B('**Repeat neurological and Doppler examination.**','Progression to motor weakness changes the urgency; symptom duration alone does not establish viability.')])],table=(['Category','Sensory/motor findings','Doppler'],[['I','No loss/weakness','Arterial +; venous +'],['IIa','Toe sensory loss; no weakness','Arterial often −; venous +'],['IIb','Beyond toes; mild/moderate weakness','Arterial −; venous +'],['III','Profound anesthesia; paralysis/rigor','Arterial −; venous −']]))

Q('Initial Anticoagulation in Acute Limb Ischemia','A patient has an acutely cold painful foot from suspected arterial occlusion. There is no active bleeding, HIT history or evidence of aortic dissection. While urgent vascular treatment is arranged, what should be started?',
 'Systemic intravenous unfractionated heparin',[('Aspirin alone while waiting for angiographic confirmation','Antiplatelet therapy may be appropriate for long-term prevention but does not replace immediate systemic anticoagulation in eligible ALI.'),('Warfarin without parenteral anticoagulation','Warfarin has delayed onset and may later address an embolic indication; it is unsuitable as sole immediate anticoagulation here.'),('Low-dose rivaroxaban 2.5 mg twice daily','The vascular prevention dose is not a treatment regimen for acute arterial occlusion requiring immediate titratable anticoagulation.')],
 [('Purpose',[B('**UFH limits thrombus propagation and further embolization.**','Its rapid onset, short half-life and reversibility suit urgent procedural care; it does not by itself guarantee reperfusion.')]),
 ('Administration and Exceptions',[B('**Use an institutional IV protocol with laboratory-guided titration.**','ESVS describes an initial 5,000 IU or 70–100 IU/kg bolus, followed by infusion adjusted to response and ACT/aPTT; procedural/thrombolysis regimens differ.'),B('**Check bleeding, platelets and contraindications.**','HIT requires a non-heparin strategy; suspected dissection or major bleeding changes the immediate plan.'),B('**Do not delay vascular assessment or revascularization** while awaiting anticoagulant effect.')])],refs=('pad','ali'))

Q('Immediately Threatened Limb','A patient with acute arterial occlusion has forefoot sensory loss extending beyond the toes and new ankle dorsiflexion weakness. Venous Doppler remains audible. What is the best management priority?',
 'Emergency revascularization using the fastest appropriate available strategy',[('Catheter alteplase infusion with planned next-day angiographic reassessment','Catheter lysis may suit selected salvageable limbs, but motor weakness requires rapid reperfusion; a prolonged infusion with delayed reassessment risks irreversible progression.'),('Therapeutic heparin with serial examinations before deciding on intervention','Heparin limits propagation but does not reliably remove the occlusion; motor deficit should trigger emergency restoration of flow.'),('Primary amputation with subsequent embolic-source investigation','Mild/moderate weakness with preserved venous signal can be salvageable category IIb; it is not equivalent to fixed paralysis/rigor of category III.')],
 [('Why Motor Deficit Matters',[B('**Rutherford IIb:** salvageable only with immediate treatment.','Neuromuscular dysfunction indicates severe ischemia; a historical time cutoff cannot substitute for the current examination.')]),
 ('Emergency Sequence',[B('**Anticoagulate if eligible, provide analgesia and mobilize vascular expertise.**'),B('**Choose rapid surgical, endovascular or hybrid reperfusion** by anatomy, cause and local capability.','Slow thrombolysis alone may be inappropriate; selected rapidly initiated catheter strategies can be used by experienced teams.'),B('**Monitor for compartment syndrome and metabolic reperfusion injury**, including potassium, acidosis, CK and renal function.')])],ordered=['Emergency Sequence'],flow=['Recognize IIb','Immediate vascular intervention','Reperfusion and compartment monitoring'])

Q('Irreversible Limb Ischemia','A cold mottled limb has fixed anesthesia, rigid paralysis and no arterial or venous Doppler signals on expert assessment. Which strategy is appropriate?',
 'Primary amputation of nonviable tissue rather than attempted reperfusion',[('Prolonged catheter thrombolysis to test whether tissue recovers','Thrombolysis can help salvageable ischemia, but established nonviability will not be reversed and exposes the patient to bleeding and reperfusion toxicity.'),('Emergency bypass to restore flow before reassessing the rigid limb','Revascularizing irreversibly necrotic muscle can release potassium, acid and myoglobin without salvaging function; confirmed category III should not undergo routine reperfusion.'),('Heparin alone with delayed outpatient review','Anticoagulation cannot reverse necrosis; ongoing nonviable tissue and systemic risk require urgent definitive surgical management.')],
 [('Category III',[B('**Profound anesthesia, fixed paralysis/rigor and absent venous flow** support irreversible ischemia.','The diagnosis requires expert clinical assessment; absent pulses alone are insufficient.')]),
 ('Protect the Patient',[B('**Primary amputation/source control** is indicated when tissue is truly nonviable.'),B('**Resuscitate and monitor potassium, acid–base state and renal function.**','Reperfusion of dead muscle risks hyperkalemia, acidosis, rhabdomyolysis and cardiovascular collapse.'),B('**Plan rehabilitation and prevention**, including contralateral-limb assessment and treatment of the embolic or atherosclerotic cause.')])])

Q('Compartment Syndrome After Revascularization','After successful embolectomy, a patient develops escalating calf pain, tense compartments and pain on passive toe movement. Pedal Doppler signals remain present. What is the best next action?',
 'Urgent assessment for compartment syndrome and fasciotomy when clinically indicated',[('Reassurance because arterial Doppler signals are present','Compartment pressure can impair microcirculation despite large-artery flow; palpable pulses or Doppler signals do not exclude compartment syndrome.'),('Escalate opioid analgesia and wait for pulse loss','Analgesia is supportive, but waiting for late vascular signs risks irreversible nerve and muscle injury.'),('Start anticoagulation for presumed DVT without surgical assessment','DVT can cause swelling, but tense compartments and passive-stretch pain after reperfusion demand urgent compartment evaluation before attributing symptoms to venous disease.')],
 [('Recognition',[B('**Reperfusion edema raises pressure within a closed fascial space.**','Disproportionate pain, passive-stretch pain, tension and neurological change are important; pulses may persist.')]),
 ('Treatment',[B('**Urgent surgical decompression** is required when the diagnosis is established.','Pressure measurement can help an uncertain examination but must not delay treatment in a clear clinical syndrome.'),B('**Four-compartment leg fasciotomy** is commonly required; selected high-risk prolonged ischemia may warrant prophylactic fasciotomy.'),B('**Monitor systemic reperfusion injury:** potassium, CK, acidosis, urine output and creatinine; treat abnormalities promptly.')])])

Q('Selecting Catheter-Directed Thrombolysis','A patient has acute bypass graft thrombosis with toe-only sensory loss, preserved motor function and venous flow. There is no major bleeding contraindication, and a monitored vascular service can begin treatment promptly. Which approach is reasonable?',
 'Catheter-directed thrombolysis with reassessment and treatment of the underlying lesion',[('Systemic full-dose IV thrombolysis as the standard preferred route','Catheter-directed therapy delivers drug into thrombus and is an established selected-limb strategy; systemic thrombolysis is not the preferred ALI approach.'),('Observation on antiplatelet therapy until the graft recanalizes','A threatened limb requires urgent assessment/reperfusion; spontaneous recanalization cannot be relied upon to preserve tissue.'),('Primary amputation because a bypass graft has thrombosed','Graft thrombosis does not itself establish nonviability; preserved motor function and limited sensory loss support a salvageable limb.')],
 [('Who May Benefit',[B('**Selected Rutherford IIa limbs** allow time for catheter thrombus treatment when bleeding risk and anatomy are suitable.','IIb requires a faster strategy; III is not a lysis indication.')]),
 ('Protocol and Monitoring',[B('**Alteplase commonly 0.5–1 mg/hour intra-arterially** under a specialist protocol.','Dose, duration and concurrent heparin differ from systemic thrombolysis; monitor access bleeding, hemoglobin and clinical perfusion.'),B('**Exclude major contraindications**, including active bleeding and important recent intracranial events.'),B('**Correct the cause of thrombosis**, such as graft anastomotic stenosis, after thrombus clearance; reassess promptly if neurological status worsens.')])],refs=('ali','pad'))

Q('Embolic Versus In-Situ Arterial Occlusion','A patient with untreated atrial fibrillation develops abrupt severe unilateral leg pain. There was no preceding claudication; pulses in the opposite leg are normal. Which mechanism is most likely?',
 'Cardiac arterial embolism',[('Acute thrombosis of advanced chronic multilevel PAD','In-situ thrombosis more often accompanies previous claudication, diffuse disease or abnormal contralateral pulses; the sudden isolated event with AF favors embolism.'),('Cholesterol crystal embolization','Cholesterol emboli often cause distal blue toes with preserved proximal pulses and systemic small-vessel findings, rather than abrupt major-limb arterial occlusion.'),('Chronic venous insufficiency','Venous insufficiency produces edema and chronic skin changes, not an abrupt arterial perfusion deficit in the setting of an embolic source.')],
 [('Clues to the Cause',[B('**Embolism:** abrupt onset, cardiac source, previously asymptomatic limb and relatively normal opposite limb.','These are probabilistic clues; imaging and operative findings establish anatomy.'),B('**Thrombosis:** underlying plaque, prior bypass/stent, aneurysm or a preceding PAD history.')]),
 ('Treat Now, Investigate in Parallel',[B('**Urgent viability assessment, heparin if eligible and reperfusion planning** take priority.'),B('**ECG, echocardiography and rhythm assessment** identify the source without delaying limb salvage.','Long-term anticoagulation is indicated for appropriate AF-related embolism; vascular-dose rivaroxaban plus aspirin is not a substitute for an AF regimen.')])])
